function maxRevenue(inventory: number[], orders: number): number {
  const MOD = 1000000007n;
  const a = [...inventory].sort((x, y) => y - x).map(BigInt);
  a.push(0n);
  const tri = (lo: bigint, hi: bigint) => (lo + hi) * (hi - lo + 1n) / 2n; // lo + ... + hi
  let left = BigInt(orders), total = 0n;
  for (let i = 0; i < a.length - 1 && left > 0n; i++) {
    const width = BigInt(i + 1), top = a[i], next = a[i + 1];
    if (top === next) continue;
    const layer = width * (top - next);
    if (left >= layer) {
      total += width * tri(next + 1n, top);
      left -= layer;
    } else {
      const rows = left / width, extra = left % width; // full price levels, then a partial one
      total += width * tri(top - rows + 1n, top) + extra * (top - rows);
      left = 0n;
    }
  }
  return Number(total % MOD);
}

