    def maxRevenue(self, inventory: List[int], orders: int) -> int:
        a = sorted(inventory, reverse=True) + [0]
        tri = lambda lo, hi: (lo + hi) * (hi - lo + 1) // 2
        total = 0
        for i in range(len(a) - 1):
            if orders == 0:
                break
            width, top, nxt = i + 1, a[i], a[i + 1]
            if top == nxt:
                continue
            layer = width * (top - nxt)
            if orders >= layer:
                total += width * tri(nxt + 1, top)
                orders -= layer
            else:
                rows, extra = divmod(orders, width)
                total += width * tri(top - rows + 1, top) + extra * (top - rows)
                orders = 0
        return total % 1000000007

