function maxRevenue(inventory: number[], orders: number): number {
  const above = (t: number) => {
    let s = 0;
    for (const a of inventory) if (a > t) s += a - t; // at most 10^14, exact in a double
    return s;
  };
  let lo = 0, hi = Math.max(...inventory);
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (above(mid) <= orders) hi = mid; else lo = mid + 1;
  }
  const T = BigInt(lo);
  let left = BigInt(orders), total = 0n;
  for (const x of inventory) {
    const a = BigInt(x);
    if (a > T) {
      total += (T + 1n + a) * (a - T) / 2n;
      left -= a - T;
    }
  }
  total += left * T;
  return Number(total % 1000000007n);
}

